const packageFor = (price, name, imageCount, summary, tags) => ({
  name,
  price,
  editedImages: imageCount,
  looks: 1,
  kinds: [...new Set([
    ...(tags.includes('Personal branding') && /brand|personal/i.test(`${name} ${summary}`) ? ['Personal branding'] : []),
    ...(tags.includes('Team headshots') && /team|group/i.test(`${name} ${summary}`) ? ['Team headshots'] : []),
    ...(/mini|quickie|quick-fix|just the basics|linkedin/i.test(name) ? ['Mini session'] : []),
    ...(/one look|one outfit|single look/i.test(summary) ? ['Single look'] : []),
    ...(/two looks|three looks|four looks|five looks|unlimited looks|multiple looks|\d+ looks/i.test(summary) ? ['Multi-look'] : []),
  ])],
  summary,
});

const mappedProviders = [...discoveredProviders, ...verifiedBatch].map(([id, name, subtitle, neighborhood, city, specialties, source, price, packageName, editedImages, setting, description, visual]) => {
  const pkg = packageFor(price, packageName, editedImages, description, specialties);
  return {
    id, name, subtitle, neighborhood, city, specialties, source, checked: 'Oct 2026', description, visual,
    settings: setting.split(' + '), startingPrice: price, featuredPackage: pkg, packages: [pkg],
  };
});

const nonProviderHosts = new Set(['www.photographer.org', 'photographer.org', 'www.bwayheadshots.com', 'bwayheadshots.com']);
function officialFaviconFor(source) {
  try {
    const page = new URL(source);
    if (page.protocol !== 'https:' || nonProviderHosts.has(page.hostname.toLowerCase())) return null;
    return `${page.origin}/favicon.ico`;
  } catch {
    return null;
  }
}

export const photographers = [...originalPhotographers, ...mappedProviders].map(photographer => ({
  ...photographer,
  logoUrl: photographerBranding[photographer.id]?.logoUrl ?? officialFaviconFor(photographer.source),
  logoKind: photographerBranding[photographer.id]?.logoUrl
    ? (/favicon|\.ico(?:\?|$)/i.test(photographerBranding[photographer.id].logoUrl) ? 'favicon' : 'brand')
    : officialFaviconFor(photographer.source) ? 'favicon' : 'unavailable',
  instagramUrl: photographerBranding[photographer.id]?.instagramUrl ?? null,
}));
